	defb	44h,52h,45h,53h,55h,00h

; Счётчикsoftware-delay PDM-бита (LDA 0733/DCR/JNZ в func_speak_phoneme). Задаёт каденс бита-бэнга (~40 T-c на OUT 00h → ~37 кГц при такте машины). Косвенно = частота дискретизации речи.
